package com.timetravel.engine;
import com.timetravel.model.*; import java.util.*;
public final class ConsequenceEngine {
    private static final Map<String,String> DOMAINS=Map.ofEntries(Map.entry("technology","Technology"),Map.entry("productivity","Economy"),Map.entry("trade","Economy"),Map.entry("employment","Employment"),Map.entry("jobs","Employment"),Map.entry("energy","Energy"),Map.entry("education","Education"),Map.entry("population","Population"),Map.entry("health","Health"),Map.entry("climate","Environment"),Map.entry("space","Technology"),Map.entry("research","Technology"));
    public List<Consequence> calculate(Event event,ModificationType type){int sign=type==ModificationType.PREVENT||type==ModificationType.DECREASE_IMPACT?-1:1;int base=Math.max(2,event.importance()*2);List<Consequence> out=new ArrayList<>();for(int i=0;i<event.possibleConsequences().size();i++){String phrase=event.possibleConsequences().get(i);String key=phrase.toLowerCase(Locale.ROOT);String domain=DOMAINS.entrySet().stream().filter(e->key.contains(e.getKey())).map(Map.Entry::getValue).findFirst().orElse(switch(event.category()){case ECONOMY->"Economy";case SPACE,SCIENCE,TECHNOLOGY->"Technology";case ENVIRONMENT->"Environment";default->"Society";});int impact=sign*(base/(i+1));out.add(new Consequence(domain,impact,phrase,1));if(i==0&&event.importance()>=7)out.add(new Consequence("Society",Math.max(1,impact/2),"Downstream response to "+phrase,2));}return out;}
    public void apply(Timeline t,List<Consequence> consequences){for(Consequence c:consequences){t.consequences().add(c);t.metrics().merge(c.domain(),c.impact(),Integer::sum);}}
}
